create table commerce_product_price_history(id bigint generated always as identity primary key,business_id uuid not null,owner_id uuid not null,product_id uuid not null,custo_anterior numeric(14,4),custo_novo numeric(14,4),preco_anterior numeric(14,2),preco_novo numeric(14,2),motivo text not null default 'alteracao',changed_by uuid default auth.uid(),created_at timestamptz not null default now(),foreign key(product_id,business_id,owner_id) references commerce_products(id,business_id,owner_id) on delete cascade);
create index commerce_price_history_product_idx on commerce_product_price_history(product_id,created_at desc);
alter table commerce_product_price_history enable row level security;
create policy commerce_price_history_tenant on commerce_product_price_history for select using(owner_id=commerce_owner_atual());
create or replace function commerce_registrar_historico_preco()returns trigger language plpgsql security invoker set search_path=public as $$begin if old.preco_venda is distinct from new.preco_venda or old.custo_medio is distinct from new.custo_medio then insert into commerce_product_price_history(business_id,owner_id,product_id,custo_anterior,custo_novo,preco_anterior,preco_novo,motivo)values(new.business_id,new.owner_id,new.id,old.custo_medio,new.custo_medio,old.preco_venda,new.preco_venda,case when old.custo_medio is distinct from new.custo_medio then 'custo_ou_preco' else 'preco' end);end if;return new;end;$$;
create trigger commerce_product_price_history_trigger after update of custo_medio,preco_venda on commerce_products for each row execute function commerce_registrar_historico_preco();
